// Pinned Go1.27.1: TestReplaceAll string channel; complete TestFindStringIndex.
using TypeScript.Scanner;
using TypeScript.RegularExpressions;

namespace LanguageServices.Checks;
public static class RegexReplacementChecks
{
    public static readonly string[] Names = ["TestReplaceAll.ReplaceAllString", "TestFindStringIndex"];
    public static int RunAll()
    {
        foreach (var name in Names)
            Run(name);
        return Names.Length;
    }

    public static void Run(string name)
    {
        if (name == Names[0])
        {
            foreach (var(pattern, replacement, input, expected)in Replacements)
            {
                var actual = GoRegexp.MustCompile(pattern).ReplaceAllString(input, replacement);
                if (!actual.EqualsValue(expected))
                    throw new InvalidOperationException("ReplaceAllString differs: " + pattern.Materialize());
            }
        }
        else if (name == Names[1])
        {
            foreach (var(pattern, text, maximum, expected)in FindIndices)
            {
                var actual = GoRegexp.MustCompile(pattern).FindStringIndex(text);
                if (maximum == 0)
                    continue; // Original testFindIndex deliberately asserts no match observation.
                if (expected == null ? !actual.IsNil : actual.IsNil || actual.Count != 2 || actual[0] != expected[0] || actual[1] != expected[1])
                    throw new InvalidOperationException("FindStringIndex differs: " + pattern.Materialize());
            }
        }
        else
            throw new ArgumentOutOfRangeException(nameof(name));
    }

